(function(){
'use strict';
const Core=window.MiyarEnterpriseCore;if(!Core)return;
const KEY='miyar-institution-profile-v1',SCHEMA='miyar-institution-profile/1.0';
const nativeFetch=window.fetch.bind(window);let capturedToken='',capturedOrigin='',remoteLoaded=false;
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function ar(){return document.documentElement.lang!=='en';}function t(a,b){return ar()?a:b;}function norm(v){return Core.normalize(v);}
function defaultProfile(){return {schema:SCHEMA,version:0,organizationName:'',units:[],gradeStructure:{name:'',methodology:'',grades:[]},approvedBy:'',approvedOn:'',updatedAt:''};}
function normalizeProfile(raw){
 const p=raw&&typeof raw==='object'?structuredClone(raw):defaultProfile();p.schema=SCHEMA;p.version=Number.isInteger(Number(p.version))?Number(p.version):0;p.organizationName=String(p.organizationName||'').slice(0,200);p.approvedBy=String(p.approvedBy||'').slice(0,200);p.approvedOn=String(p.approvedOn||'').slice(0,10);p.updatedAt=String(p.updatedAt||'');
 p.units=Array.isArray(p.units)?p.units.slice(0,500).map(u=>({code:String(u.code||'').trim().slice(0,40),nameAr:String(u.nameAr||'').trim().slice(0,200),nameEn:String(u.nameEn||'').trim().slice(0,200),parentCode:String(u.parentCode||'').trim().slice(0,40),leaderTitle:String(u.leaderTitle||'').trim().slice(0,200)})).filter(u=>u.code&&u.nameAr&&u.nameEn):[];
 const g=p.gradeStructure&&typeof p.gradeStructure==='object'?p.gradeStructure:{};p.gradeStructure={name:String(g.name||'').slice(0,200),methodology:String(g.methodology||'').slice(0,200),grades:Array.isArray(g.grades)?g.grades.slice(0,100).map(x=>({id:String(x.id||'').trim().slice(0,40),labelAr:String(x.labelAr||'').trim().slice(0,120),labelEn:String(x.labelEn||'').trim().slice(0,120),level:String(x.level||'custom').trim().toLowerCase().slice(0,40),...(Number.isInteger(x.minPoints)&&Number.isInteger(x.maxPoints)?{minPoints:x.minPoints,maxPoints:x.maxPoints}:{})})).filter(x=>x.id&&x.labelAr&&x.labelEn):[]};return p;
}
function read(){try{return normalizeProfile(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{return defaultProfile();}}
function saveLocal(profile,increment=false){const p=normalizeProfile(profile);if(increment)p.version=Math.max(1,Number(read().version||0)+1);p.updatedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(p));window.dispatchEvent(new CustomEvent('miyar:institution-profile',{detail:p}));return p;}
function profileExample(){return normalizeProfile({schema:SCHEMA,organizationName:'Example Organization',units:[{code:'CORP',nameAr:'المؤسسة',nameEn:'Corporate',parentCode:'',leaderTitle:'Chief Executive Officer'},{code:'HC',nameAr:'رأس المال البشري',nameEn:'Human Capital',parentCode:'CORP',leaderTitle:'Director, Human Capital'},{code:'FIN',nameAr:'المالية',nameEn:'Finance',parentCode:'CORP',leaderTitle:'Finance Director'},{code:'IT',nameAr:'تقنية المعلومات',nameEn:'Information Technology',parentCode:'CORP',leaderTitle:'IT Director'}],gradeStructure:{name:'Organization Grade Architecture',methodology:'Organization-approved grade architecture; formal job evaluation required',grades:[{id:'G7',labelAr:'أخصائي',labelEn:'Professional',level:'professional',minPoints:300,maxPoints:449},{id:'G9',labelAr:'أخصائي أول',labelEn:'Senior Professional',level:'senior',minPoints:450,maxPoints:599},{id:'G11',labelAr:'مدير',labelEn:'Manager',level:'manager',minPoints:600,maxPoints:749},{id:'G13',labelAr:'مدير إدارة',labelEn:'Director',level:'director',minPoints:750,maxPoints:899},{id:'G15',labelAr:'تنفيذي',labelEn:'Executive',level:'executive',minPoints:900,maxPoints:1000}]},approvedBy:'CHRO / Authorized authority',approvedOn:'2026-09-01'});}
function unitPath(profile,code){const map=new Map(profile.units.map(u=>[u.code,u])),rows=[];let current=map.get(code),guard=0;while(current&&guard++<20){rows.unshift(ar()?current.nameAr:current.nameEn);current=map.get(current.parentCode);}return rows.join(' / ');}
function matchUnit(profile,department){const q=norm(department);if(!q)return null;const scored=profile.units.map(u=>{const names=[norm(u.nameAr),norm(u.nameEn),norm(u.code)],exact=names.some(x=>x===q),contains=names.some(x=>x.includes(q)||q.includes(x));return {u,score:exact?100:contains?80:0};}).filter(x=>x.score).sort((a,b)=>b.score-a.score);return scored[0]?.u||null;}
function levelId(value){const n=norm(value);if(/executive|chief|vp|vice president|تنفيذي|نائب الرئيس/.test(n))return'executive';if(/director|head level|مدير اداره|مدير إدارة|رئيس/.test(n))return'director';if(/manager|مدير/.test(n))return'manager';if(/senior|lead|اول|أول/.test(n))return'senior';if(/entry|junior|مبتد/.test(n))return'entry';return'professional';}
function matchGrade(profile,level){const id=levelId(level),rows=profile.gradeStructure.grades.filter(g=>g.level===id);return rows[0]||null;}
function parseRows(text,kind){const rows=String(text||'').split('\n').map(x=>x.trim()).filter(Boolean);return rows.map((line,index)=>{const cells=line.split('|').map(x=>x.trim());if(kind==='unit'){if(cells.length<3)throw Error(t('سطر الهيكل '+(index+1)+' يحتاج: الرمز | العربي | الإنجليزي.','Structure row '+(index+1)+' needs: code | Arabic | English.'));return {code:cells[0],nameAr:cells[1],nameEn:cells[2],parentCode:cells[3]||'',leaderTitle:cells[4]||''};}if(cells.length<4)throw Error(t('سطر الدرجة '+(index+1)+' يحتاج: الدرجة | العربي | الإنجليزي | المستوى.','Grade row '+(index+1)+' needs: grade | Arabic | English | level.'));const min=cells[4]===''||cells[4]===undefined?undefined:Number(cells[4]),max=cells[5]===''||cells[5]===undefined?undefined:Number(cells[5]);if((min!==undefined||max!==undefined)&&(!Number.isInteger(min)||!Number.isInteger(max)))throw Error(t('نقاط الدرجات يجب أن تكون أعدادًا صحيحة.','Grade points must be integers.'));return {id:cells[0],labelAr:cells[1],labelEn:cells[2],level:cells[3].toLowerCase(),...(min!==undefined&&max!==undefined?{minPoints:min,maxPoints:max}:{})};});}
function serializeUnits(p){return p.units.map(u=>[u.code,u.nameAr,u.nameEn,u.parentCode,u.leaderTitle].join(' | ')).join('\n');}
function serializeGrades(p){return p.gradeStructure.grades.map(g=>[g.id,g.labelAr,g.labelEn,g.level,g.minPoints??'',g.maxPoints??''].join(' | ')).join('\n');}
function capture(input,init){try{const headers=new Headers(init?.headers||(input instanceof Request?input.headers:undefined)),auth=headers.get('Authorization');if(auth?.startsWith('Bearer ')){capturedToken=auth.slice(7);capturedOrigin=new URL(typeof input==='string'?input:input.url,location.href).origin;}}catch{}}
window.fetch=function(input,init){capture(input,init);return nativeFetch(input,init);};
async function server(path,method='GET',body){if(!capturedToken||!capturedOrigin)throw Error(t('سجّل الدخول إلى المؤسسة أولًا.','Sign in to the organization first.'));const r=await nativeFetch(capturedOrigin+path,{method,headers:{Authorization:'Bearer '+capturedToken,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(30000)});let value=null;try{value=await r.json();}catch{}if(!r.ok)throw Error(typeof value?.detail==='string'?value.detail:t('تعذر حفظ إعداد المؤسسة.','Could not save institution setup.'));return value;}
async function syncRemote(){if(!capturedToken||remoteLoaded)return read();const r=await server('/api/v1/settings/institution-profile');remoteLoaded=true;return saveLocal(r.profile,false);}
function editor(host,remote){const p=read();host.innerHTML='<section class="institution-card"><div class="institution-head"><div><span>PHASE 1 FOUNDATION</span><h3>'+t('الإعداد المؤسسي لمرة واحدة','One-time institutional setup')+'</h3><p>'+t('اعتمد الهيكل التنظيمي وهيكل الدرجات مرة واحدة، ثم يستخدمهما محرك OD في كل طلب جديد.','Approve the organization structure and grade architecture once; the OD engine reuses them for every new request.')+'</p></div><span class="institution-status">'+(p.version?t('v','v')+p.version:t('غير معد','Not configured'))+'</span></div><div class="ent-form-grid"><label class="ent-field">'+t('اسم الجهة','Organization name')+'<input data-inst-org value="'+esc(p.organizationName)+'"></label><label class="ent-field">'+t('اعتمد بواسطة','Approved by')+'<input data-inst-approved-by value="'+esc(p.approvedBy)+'"></label><label class="ent-field">'+t('تاريخ الاعتماد','Approval date')+'<input data-inst-approved-on type="date" value="'+esc(p.approvedOn)+'"></label><label class="ent-field">'+t('اسم هيكل الدرجات','Grade structure name')+'<input data-inst-grade-name value="'+esc(p.gradeStructure.name)+'"></label><label class="ent-field">'+t('منهجية/مرجع الدرجات','Grade methodology/reference')+'<input data-inst-method value="'+esc(p.gradeStructure.methodology)+'"></label></div><label class="ent-field">'+t('الهيكل التنظيمي — سطر لكل وحدة','Organization structure — one unit per line')+'<textarea data-inst-units rows="7" dir="auto" placeholder="HC | رأس المال البشري | Human Capital | CORP | Director, Human Capital">'+esc(serializeUnits(p))+'</textarea><small>'+t('الصيغة: الرمز | الاسم العربي | الاسم الإنجليزي | رمز الوحدة الأب | مسمى قائد الوحدة','Format: code | Arabic name | English name | parent code | unit leader title')+'</small></label><label class="ent-field">'+t('هيكل الدرجات — سطر لكل درجة','Grade architecture — one grade per line')+'<textarea data-inst-grades rows="7" dir="auto" placeholder="G11 | مدير | Manager | manager | 600 | 749">'+esc(serializeGrades(p))+'</textarea><small>'+t('المستويات: entry / professional / senior / manager / director / executive. النقاط اختيارية.','Levels: entry / professional / senior / manager / director / executive. Point ranges are optional.')+'</small></label><div class="action-row"><button type="button" class="button button-primary" data-inst-save>'+t(remote?'حفظ واعتماد للمؤسسة':'حفظ على هذا الجهاز',remote?'Save institutional profile':'Save on this device')+'</button><button type="button" class="button button-outline" data-inst-example>'+t('تحميل مثال','Load example')+'</button><button type="button" class="button button-outline" data-inst-export>'+t('تصدير JSON','Export JSON')+'</button></div><p data-inst-message class="ent-note">'+t(remote?'سيُحفظ الإصدار على خادم المؤسسة مع سجل تدقيق.':'الإعداد المحلي للتجربة فقط؛ تسجيل الدخول كمسؤول يتيح حفظه للمؤسسة.',remote?'This version will be saved to the organization server with an audit record.':'Local setup is for trial use; an administrator can persist it to the organization server.')+'</p></section>';
 const msg=host.querySelector('[data-inst-message]');host.querySelector('[data-inst-example]').onclick=()=>{const e=profileExample();host.querySelector('[data-inst-org]').value=e.organizationName;host.querySelector('[data-inst-approved-by]').value=e.approvedBy;host.querySelector('[data-inst-approved-on]').value=e.approvedOn;host.querySelector('[data-inst-grade-name]').value=e.gradeStructure.name;host.querySelector('[data-inst-method]').value=e.gradeStructure.methodology;host.querySelector('[data-inst-units]').value=serializeUnits(e);host.querySelector('[data-inst-grades]').value=serializeGrades(e);msg.textContent=t('تم تحميل مثال قابل للتعديل.','Editable example loaded.');};
 host.querySelector('[data-inst-export]').onclick=()=>{const blob=new Blob([JSON.stringify(read(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='miyar-institution-profile.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);};
 host.querySelector('[data-inst-save]').onclick=async()=>{try{const base=read(),profile=normalizeProfile({...base,organizationName:host.querySelector('[data-inst-org]').value,approvedBy:host.querySelector('[data-inst-approved-by]').value,approvedOn:host.querySelector('[data-inst-approved-on]').value,units:parseRows(host.querySelector('[data-inst-units]').value,'unit'),gradeStructure:{name:host.querySelector('[data-inst-grade-name]').value,methodology:host.querySelector('[data-inst-method]').value,grades:parseRows(host.querySelector('[data-inst-grades]').value,'grade')}});let saved;if(remote){const r=await server('/api/v1/settings/institution-profile','POST',{profile,reason:'Approved one-time OD institution structure and grade architecture configuration'});saved=saveLocal(r.profile,false);}else saved=saveLocal(profile,true);msg.textContent=t('حُفظ الإعداد. يستخدمه محرك OD في الطلبات الجديدة؛ المخرجات السابقة لا تتغير.','Setup saved. The OD engine uses it for new requests; existing outputs are unchanged.');host.querySelector('.institution-status').textContent='v'+saved.version;renderContext();}catch(error){msg.textContent=error.message;}}
}
function renderContext(){const panel=document.getElementById('miyar-od-workbench');if(!panel)return;let box=panel.querySelector('[data-institution-context]');if(!box){box=document.createElement('div');box.dataset.institutionContext='true';box.className='institution-context';const foundation=panel.querySelector('.od-foundation');foundation?.after(box);}const p=read(),configured=p.units.length||p.gradeStructure.grades.length;box.innerHTML='<div><strong>'+t('الإعداد المؤسسي','Institution setup')+'</strong><span>'+ (configured?t('مفعّل · ','Configured · ')+p.units.length+t(' وحدات · ',' units · ')+p.gradeStructure.grades.length+t(' درجات',' grades'):t('غير معد — ستبقى الوحدة والدرجة بحاجة مراجعة يدوية.','Not configured — unit and grade will remain manual review items.'))+'</span></div><button type="button" class="ent-link" data-inst-open>'+t('إعداد','Configure')+'</button>';box.querySelector('[data-inst-open]').onclick=openDialog;}
function openDialog(){const dialog=document.createElement('dialog');dialog.className='institution-dialog';dialog.innerHTML='<div class="institution-dialog-actions"><button type="button" class="button button-outline" data-inst-close>'+t('إغلاق','Close')+'</button></div><div data-inst-dialog-body></div>';document.body.append(dialog);editor(dialog.querySelector('[data-inst-dialog-body]'),false);dialog.querySelector('[data-inst-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();}
function decorateOD(){const panel=document.getElementById('miyar-od-workbench'),result=panel?.querySelector('[data-od-result]');if(!panel||!result||!result.children.length)return;result.querySelector('[data-inst-match]')?.remove();const p=read(),dept=panel.querySelector('[data-od-department]')?.value||document.querySelector('[data-field=department]')?.value||'',level=result.querySelector('.od-level')?.textContent||panel.querySelector('[data-od-level]')?.value||'',unit=matchUnit(p,dept),grade=matchGrade(p,level),block=document.createElement('div');block.dataset.instMatch='true';block.className='institution-match';block.innerHTML='<div><span>'+t('الموقع التنظيمي','Organization placement')+'</span><strong>'+(unit?esc(unit.code+' · '+unitPath(p,unit.code)):'—')+'</strong><small>'+esc(unit?.leaderTitle||t('لا يوجد تطابق مؤسسي بعد','No institution unit matched yet'))+'</small></div><div><span>'+t('الدرجة المقترحة من هيكل الجهة','Grade proposal from organization structure')+'</span><strong>'+(grade?esc(grade.id+' · '+(ar()?grade.labelAr:grade.labelEn)):'—')+'</strong><small>'+t('اقتراح قبل التقييم فقط؛ نتيجة التقييم الرسمية هي المرجع النهائي.','Pre-evaluation proposal only; formal job evaluation remains authoritative.')+'</small></div>';const target=result.querySelector('.od-grade-note');target?target.before(block):result.prepend(block);}
function applyInstitution(){const p=read(),od=document.getElementById('miyar-od-workbench'),dept=od?.querySelector('[data-od-department]')?.value||document.querySelector('[data-field=department]')?.value||'',level=document.querySelector('[data-field=seniority]')?.value||'',unit=matchUnit(p,dept),grade=matchGrade(p,level);if(unit){const field=document.querySelector('[data-field=department]');if(field){field.value=ar()?unit.nameAr:unit.nameEn;field.dispatchEvent(new Event('input',{bubbles:true}));}const select=document.getElementById('ent-department');if(select){const option=[...select.options].find(o=>[unit.nameAr,unit.nameEn].some(n=>norm(o.textContent)===norm(n)));if(option){select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));}}const manager=document.querySelector('[data-field=manager]');if(manager&&!manager.value&&unit.leaderTitle){manager.value=unit.leaderTitle;manager.dispatchEvent(new Event('input',{bubbles:true}));}}if(grade){const seniority=document.querySelector('[data-field=seniority]');if(seniority&&!seniority.value.includes(grade.id)){seniority.value=seniority.value+' · '+t('درجة مقترحة ','Proposed grade ')+grade.id;seniority.dispatchEvent(new Event('input',{bubbles:true}));}}}
const priorImport=Core.importDraft.bind(Core);Core.importDraft=function(payload){const clean=priorImport(payload),source=payload?.content||{},p=read(),unit=matchUnit(p,source.department),grade=matchGrade(p,source.recommendedLevel||source.seniority);if(p.version){clean.organizationProfileVersion=String(p.version);if(p.gradeStructure.name)clean.gradeArchitectureName=p.gradeStructure.name;clean.gradeArchitectureVersion=String(p.version);}if(unit){clean.orgUnitCode=unit.code;clean.orgUnitPath=unitPath(p,unit.code);}if(grade)clean.proposedGrade=grade.id+' · '+(ar()?grade.labelAr:grade.labelEn);return clean;};
function connectionEditor(){const host=document.getElementById('ent-admin');if(!host||host.querySelector('[data-institution-admin]'))return;const isAdmin=host.children.length>0;if(!isAdmin)return;const wrap=document.createElement('div');wrap.dataset.institutionAdmin='true';host.prepend(wrap);const mount=async()=>{try{await syncRemote();}catch{}editor(wrap,Boolean(capturedToken));};mount();}
document.addEventListener('click',event=>{if(event.target.closest('[data-od-generate]'))setTimeout(()=>{decorateOD();renderContext();},0);if(event.target.closest('[data-od-apply]'))setTimeout(()=>{applyInstitution();decorateOD();},0);});
window.addEventListener('miyar:navigate',event=>{const tab=event.detail?.tab;if(tab==='create')setTimeout(renderContext,0);if(tab==='connection')setTimeout(connectionEditor,0);});window.addEventListener('miyar:institution-profile',()=>{renderContext();decorateOD();});
window.MiyarInstitutionProfile={KEY,SCHEMA,read,saveLocal,matchUnit,matchGrade,unitPath,profileExample,normalizeProfile};
setTimeout(()=>{renderContext();connectionEditor();},0);
})();
